SELECT st.id,
'US_PROGRAM_OLSAT_REASONING_CLASSIFICATION_0308',
'medium',
'Which item does not belong: red, blue, green, seven?',
'green',
'seven',
'red',
'blue',
'B',
'The others are colors.',
1,
'generated-original'
FROM education_subtopics st
JOIN education_topics t ON t.id=st.topic_id
JOIN education_subjects s ON s.id=t.subject_id
WHERE s.country_code='US'
  AND s.grade_code='PROGRAM_OLSAT'
  AND s.subject_code='REASONING'
  AND t.topic_code='NONVERBAL'
  AND st.subtopic_code='CLASSIFICATION';

